    private static ulong Coef(ulong field) =>
        (field & ((1UL << CoefMantissaBits) - 1UL)) << (int)(field >> CoefMantissaBits);

    /// <summary>Series coefficient k (1-based) of piece p, Q0.64.</summary>
    public static ulong C(int k, int p) => k == 1 ? W[1][p]
        : Coef((W[2 + (k - 2) / 2][p] >> (CoefBits * ((k - 2) % 2))) & ((1UL << CoefBits) - 1UL));

    public static ulong Recip(int p) => W[0][p];
