    public static int IndexBits(int p) => (int)((W[8][p] >> 6) & 0x1FUL);
    public static bool StartsClass(int p) => ((W[8][p] >> 11) & 1UL) != 0UL;
    public static long FirstOrdinal(int p) => (long)(W[8][p] >> 12);
